fn solve(input: Vec<char>) -> Vec<char> {
    // Check the length of the input
    if input.len() < 18 {
        return vec![]; // Invalid input length
    }

    // Check the prefix "AtCoder "
    let prefix = "AtCoder ";
    let prefix_len = prefix.len();
    if input[..prefix_len].iter().collect::<String>() != prefix {
        return vec![]; // Invalid prefix
    }

    // Find the end of the name
    let name_start = prefix_len;
    let name_end = input.iter().position(|&c| c == ' ').unwrap_or(input.len() - 1);
    
    // Check if the name is valid
    if name_end <= name_start || name_end + 1 + " Contest\n".len() != input.len() {
        return vec![]; // Invalid name or format
    }

    // Check the name's first character is uppercase and the rest are lowercase
    let name_initial = input[name_start];
    if !name_initial.is_uppercase() {
        return vec![]; // Invalid name initial
    }

    for &c in &input[name_start + 1..name_end] {
        if !c.is_lowercase() {
            return vec![]; // Invalid name character
        }
    }

    // Check the suffix " Contest\n"
    let suffix = " Contest\n";
    let suffix_start = name_end;
    if input[suffix_start..].iter().collect::<String>() != suffix {
        return vec![]; // Invalid suffix
    }

    // Build the result
    return build_result(name_initial);
}

fn build_result(ch: char) -> Vec<char> {
    let mut result = Vec::new();
    result.push('A');
    result.push(ch);
    result.push('C');
    result.push('\n');
    result
}